def moves(state):
    out=[]
    for (r,c) in state:
        for dr,dc in DIRS:
            m=(r+dr,c+dc); l=(r+2*dr,c+2*dc)
            if m in state and l in CELLSET and l not in state:
                out.append(((r,c),m,l))
    return out

retained_functions.solve:
def solve(state, path, best):
    if len(state)==1:
        best.append(path); return True
    for mv in moves(state):
        s=set(state); s.discard(mv[0]); s.discard(mv[1]); s.add(mv[2])
        key=frozenset(s)
        if key in seen: continue
        seen[key]=1
        if solve(s, path+[mv], best): return True
    return False

