def blues(fr):
    out=[]
    for n in fr.segmentation['nodes']:
        if n['color']=='b': out.append((n['pixels'], tuple(map(tuple,n['boundary']))))
    return out

retained_functions.lockbb:
def lockbb(fr):
    a=fr.ascii.split('\n')
    pts=[(r,c) for r,row in enumerate(a) for c,ch in enumerate(row) if ch in 'YO']
    if not pts: return None
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    return (min(rs),min(cs),max(rs),max(cs))

